package rawdb

import (
	"context"

	"github.com/tronprotocol/go-tron/common"
)

// Only first-change accessors may use this summary. Generic iterators must
// continue to expose every repaired row. All four query bounds are exact:
// an earlier first row outside a narrower Tx window cannot prove absence when
// legacy rows have nonmonotone TxNums.
type stateHistoryQueryTailFirst struct {
	from, to, targetTx, headTx uint64
	rows                       []*StateDomainChange
	bytes                      int
}

func iterateFirstStateHistoryTail(ctx context.Context, db StateKVHistoryReader, from, to, targetTx, headTx uint64, owner common.Address, fn func(*StateDomainChange) (bool, error)) error {
	v, ok := db.(*stateHistoryQueryTailView)
	if !ok {
		return iterateStateHistoryOwnerTail(ctx, db, from, to, owner, fn)
	}
	v.mu.Lock()
	defer v.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return err
	}
	old := v.first[owner]
	if old != nil && old.from == from && old.to == to && old.targetTx == targetTx && old.headTx == headTx {
		for _, row := range old.rows {
			if err := ctx.Err(); err != nil {
				return err
			}
			cont, err := fn(cloneStateDomainChange(row))
			if err != nil || !cont {
				return err
			}
		}
		return nil
	}
	oldBytes, oldRows := 0, 0
	if old != nil {
		oldBytes, oldRows = old.bytes, len(old.rows)
	}
	next := &stateHistoryQueryTailFirst{from: from, to: to, targetTx: targetTx, headTx: headTx, bytes: 128}
	seen := make(map[string]struct{})
	var scratch []byte
	stopped, overflow := false, false
	abandon := func() { overflow = true; next.rows = nil; seen = nil; scratch = nil }
	if v.used-oldBytes+next.bytes > v.budget {
		abandon()
	}
	err := v.iterateOwnerLocked(ctx, from, to, owner, func(row *StateDomainChange) (bool, error) {
		if !overflow && stateDomainChangeInTxWindow(row, targetTx, headTx) {
			// Avoid allocating an oversized canonical key just to reject its cache row.
			if len(row.Key) > v.budget {
				abandon()
			} else {
				var keyErr error
				scratch, keyErr = appendStateDomainChangeLatestKey(scratch[:0], row)
				if keyErr != nil {
					abandon()
				} else if _, exists := seen[string(scratch)]; !exists {
					size := 320 + len(scratch) + len(row.Key) + len(row.Prev) + len(row.Next)
					if v.used-oldBytes+next.bytes+size > v.budget || v.rows-oldRows+len(next.rows)+1 > v.maxRows {
						abandon()
					} else {
						seen[string(scratch)] = struct{}{}
						next.rows = append(next.rows, cloneStateDomainChange(row))
						next.bytes += size
					}
				}
			}
		}
		cont, err := fn(row)
		if !cont {
			stopped = true
		}
		return cont, err
	})
	if err != nil {
		return err
	}
	if err = ctx.Err(); err != nil {
		return err
	}
	// An overflowing full-row owner is the only case that needs this additional
	// summary. Small owners already reuse the existing complete-row cache.
	if stopped || overflow || !v.rejected[owner] {
		return nil
	}
	if v.used-oldBytes+next.bytes > v.budget || v.rows-oldRows+len(next.rows) > v.maxRows {
		return nil
	}
	if v.first == nil {
		v.first = make(map[common.Address]*stateHistoryQueryTailFirst)
	}
	v.first[owner] = next
	v.used += next.bytes - oldBytes
	v.rows += len(next.rows) - oldRows
	return nil
}

package rawdb

import (
	"bytes"
	"context"
	"errors"
	"reflect"
	"sync"
	"testing"

	"github.com/tronprotocol/go-tron/common"
	"github.com/tronprotocol/go-tron/core/state/kvdomains"
)

func TestQueryFirstTailSummaryMatchesRepairedOracle(t *testing.T) {
	f, owner := queryTailFixture(t)
	view, closeView, err := AcquireStateHistoryReadView(f)
	if err != nil {
		t.Fatal(err)
	}
	defer closeView()
	counted := &queryTailCountView{StateHistoryReadView: view}
	cache := WithStateHistoryQueryTailCache(counted).(*stateHistoryQueryTailView)
	cache.maxRows = 128
	miss := []byte("not-in-history")
	if row, err := ReadFirstStateDomainChangeByKeyBlockRange(cache, 1, 9, 100, 1000, StateFlatDomainKVLatest, owner, 1, kvdomains.ContractStorage, miss); err != nil || row != nil {
		t.Fatal(row, err)
	}
	if counted.scans != 1 || !cache.rejected[owner] || cache.first[owner] == nil {
		t.Fatalf("summary missing: scans=%d rejected=%v first=%v", counted.scans, cache.rejected[owner], cache.first[owner])
	}
	var keys [][]byte
	for i := 0; i < 16; i++ {
		keys = append(keys, []byte{byte(i)})
	}
	keys = append(keys, miss)
	for _, flat := range []StateFlatDomain{StateFlatDomainAccountLatest, StateFlatDomainKVGeneration, StateFlatDomainKVLatest} {
		for gen := uint64(0); gen < 2; gen++ {
			for _, key := range keys {
				var want *StateDomainChange
				if err := IterateStateDomainChangesByBlockRange(view, 2, 9, func(row *StateDomainChange) (bool, error) {
					if stateDomainChangeInTxWindow(row, 100, 1000) && stateDomainChangeMatchesKey(row, flat, owner, gen, kvdomains.ContractStorage, key) {
						want = cloneStateDomainChange(row)
						return false, nil
					}
					return true, nil
				}); err != nil {
					t.Fatal(err)
				}
				got, err := ReadFirstStateDomainChangeByKeyBlockRange(cache, 1, 9, 100, 1000, flat, owner, gen, kvdomains.ContractStorage, key)
				if err != nil || !reflect.DeepEqual(got, want) {
					t.Fatalf("flat %v gen %d key %x: got %+v want %+v err %v", flat, gen, key, got, want, err)
				}
				if got != nil {
					got.Seq = 999
					if len(got.Prev) > 0 {
						got.Prev[0] ^= 0xff
					}
					if len(got.Key) > 0 {
						got.Key[0] ^= 0xff
					}
				}
			}
		}
	}
	batch, err := ReadFirstStateKVChangesByKeysBlockRange(cache, 1, 9, 100, 1000, owner, 1, kvdomains.ContractStorage, keys)
	if err != nil {
		t.Fatal(err)
	}
	for _, key := range keys {
		want, err := ReadFirstStateDomainChangeByKeyBlockRange(view, 1, 9, 100, 1000, StateFlatDomainKVLatest, owner, 1, kvdomains.ContractStorage, key)
		if err != nil || !reflect.DeepEqual(batch[string(key)], want) {
			t.Fatal("batch mismatch", err)
		}
	}
	if counted.scans != 1 {
		t.Fatalf("summary rescanned %d times", counted.scans)
	}
	if cache.used > cache.budget || cache.rows > cache.maxRows {
		t.Fatal("summary over budget")
	}
	// Generic history remains a full iterator, even after a first-only summary.
	all := 0
	if err := iterateStateHistoryTailByOwner(context.Background(), cache, 2, 9, owner, func(*StateDomainChange) (bool, error) { all++; return true, nil }); err != nil {
		t.Fatal(err)
	}
	if all <= len(cache.first[owner].rows) {
		t.Fatal("generic history replaced by first rows")
	}
	var wg sync.WaitGroup
	for i := 0; i < 12; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if _, err := ReadFirstStateDomainChangeByKeyBlockRange(cache, 1, 9, 100, 1000, StateFlatDomainKVLatest, owner, 1, kvdomains.ContractStorage, miss); err != nil {
				t.Error(err)
			}
		}()
	}
	wg.Wait()
	if counted.scans != 2 {
		t.Fatal("concurrent summary rescan", counted.scans)
	}
}

func TestQueryFirstTailExactWindowAndNonmonotoneTx(t *testing.T) {
	f := &historyViewTestFactory{KeyValueStore: NewMemoryDatabase()}
	defer f.Close()
	owner := common.Address{0x41, 9}
	key := []byte("key")
	for i, tx := range []uint64{20, 15} {
		if err := WriteStateDomainChangeRow(f, &StateDomainChange{BlockNum: 2, Seq: uint64(i + 1), TxNum: tx, FlatDomain: StateFlatDomainKVLatest, Owner: owner, Domain: kvdomains.ContractStorage, Key: key, Prev: []byte{byte(tx)}}); err != nil {
			t.Fatal(err)
		}
	}
	if err := WriteStageProgressWithHash(f, StageStateHistoryIndex, 1, common.Hash{1}); err != nil {
		t.Fatal(err)
	}
	view, release, err := AcquireStateHistoryReadView(f)
	if err != nil {
		t.Fatal(err)
	}
	defer release()
	counted := &queryTailCountView{StateHistoryReadView: view}
	cache := WithStateHistoryQueryTailCache(counted).(*stateHistoryQueryTailView)
	cache.maxRows = 1
	if _, err := ReadFirstStateDomainChangeByKeyBlockRange(cache, 1, 2, 1, 25, StateFlatDomainKVLatest, owner, 0, kvdomains.ContractStorage, []byte("missing")); err != nil {
		t.Fatal(err)
	}
	if cache.first[owner] == nil {
		t.Fatal("summary missing")
	}
	for _, head := range []uint64{25, 18, 25} {
		got, err := ReadFirstStateDomainChangeByKeyBlockRange(cache, 1, 2, 1, head, StateFlatDomainKVLatest, owner, 0, kvdomains.ContractStorage, key)
		if err != nil || got == nil {
			t.Fatal(got, err)
		}
		want := uint64(20)
		if head == 18 {
			want = 15
		}
		if got.TxNum != want {
			t.Fatalf("head %d got %d want %d", head, got.TxNum, want)
		}
	}
}

func TestQueryFirstTailIncompleteAndFailedScansNeverPublish(t *testing.T) {
	for _, mode := range []string{"early", "budget", "cancel", "cancel-mid", "callback-error", "corrupt"} {
		t.Run(mode, func(t *testing.T) {
			f, owner := queryTailFixture(t)
			if mode == "corrupt" {
				if err := f.Put(stateChangeSetKey(2, 0), append(append([]byte(nil), stateDomainChangeBlockEnvelopeMagic[:]...), stateDomainChangeBlockSharedVersion, 0xff)); err != nil {
					t.Fatal(err)
				}
			}
			view, release, err := AcquireStateHistoryReadView(f)
			if err != nil {
				t.Fatal(err)
			}
			defer release()
			cache := WithStateHistoryQueryTailCache(view).(*stateHistoryQueryTailView)
			cache.maxRows = 128
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			if mode == "budget" {
				cache.budget = 129
			}
			if mode == "cancel" {
				cancel()
			}
			err = iterateFirstStateHistoryTail(ctx, cache, 2, 9, 100, 1000, owner, func(row *StateDomainChange) (bool, error) {
				if len(row.Prev) > 0 {
					row.Prev = bytes.Clone(row.Prev)
				}
				if mode == "cancel-mid" {
					cancel()
				}
				if mode == "callback-error" {
					return false, errors.New("callback error")
				}
				return mode != "early", nil
			})
			if (mode == "cancel" || mode == "cancel-mid") && !errors.Is(err, context.Canceled) {
				t.Fatal(err)
			}
			if (mode == "corrupt" || mode == "callback-error") && err == nil {
				t.Fatal("corrupt absence")
			}
			if len(cache.first) != 0 {
				t.Fatal("incomplete summary retained")
			}
		})
	}
}

package snapshots

import (
	"context"
	"io"
	"os"
	"sync"
)

// A plain immutable accessor repeatedly reads its small header and directory
// fields. Coalesce only small reads on this open descriptor; large payloads
// still use one direct read. Validation remains in the existing callers.
// Pages never survive Close or cross a descriptor/request boundary.
type historyAccessorPages struct {
	mu    sync.Mutex
	file  *os.File
	pages *historyDirectoryPages
}

func newHistoryAccessorPages(ctx context.Context, file *os.File, size uint64) *historyAccessorPages {
	return &historyAccessorPages{file: file, pages: acquireHistoryDirectoryPages(ctx, file, 0, size)}
}

func (r *historyAccessorPages) ReadAt(dst []byte, off int64) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.pages == nil {
		return 0, os.ErrClosed
	}
	if err := contextError(r.pages.ctx); err != nil {
		return 0, err
	}
	if len(dst) == 0 || off < 0 || uint64(off) >= uint64(r.pages.end) || len(dst) > historyDirectoryPageSize {
		return r.file.ReadAt(dst, off)
	}
	// Match ReaderAt EOF semantics without fetching past the sized descriptor.
	if int64(len(dst)) > r.pages.end-off {
		count := int(r.pages.end - off)
		n, err := r.pages.ReadAt(dst[:count], off)
		if err == nil {
			err = io.EOF
		}
		return n, err
	}
	return r.pages.ReadAt(dst, off)
}

func (r *historyAccessorPages) Close() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.pages == nil {
		return os.ErrClosed
	}
	releaseHistoryDirectoryPages(r.pages)
	r.pages = nil
	return r.file.Close()
}

